<?php
require_once __DIR__.'/../app/bootstrap.php';require_admin();ensure_commerce_directory_schema();
$adminPage='commerces';$adminTitle='Directorio de comercios';$adminSubtitle='Fichas públicas vinculadas a los perfiles de vendedores';
if($_SERVER['REQUEST_METHOD']==='POST'){
 verify_csrf();$action=(string)($_POST['action']??'save');$id=max(0,(int)($_POST['id']??0));
 if($action==='delete'){$st=db()->prepare('DELETE FROM commerce_directory WHERE id=?');$st->execute([$id]);flash('success','Ficha eliminada.');redirect('commerces.php');}
 $uid=max(0,(int)($_POST['user_id']??0));$name=trim((string)($_POST['name']??''));$number=trim((string)($_POST['local_number']??''));$description=trim((string)($_POST['description']??''));
 if(mb_strlen($name)<2||mb_strlen($name)>180||mb_strlen($number)>60||mb_strlen($description)>4000)throw new RuntimeException('Revisa el nombre, número de local y descripción.');
 $check=db()->prepare("SELECT id FROM users WHERE id=? AND status='active'");$check->execute([$uid]);if(!$check->fetchColumn())throw new RuntimeException('Selecciona un usuario activo.');
 $dup=db()->prepare('SELECT id FROM commerce_directory WHERE user_id=? AND id<>?');$dup->execute([$uid,$id]);if($dup->fetchColumn())throw new RuntimeException('Este usuario ya tiene una ficha. Edítala para actualizarla.');
 $image=upload_image('image','commerce_directory');$active=isset($_POST['active'])?1:0;$featured=isset($_POST['featured'])?1:0;$sort=max(0,min(9999,(int)($_POST['sort_order']??0)));
 if($id){$q=db()->prepare('SELECT image FROM commerce_directory WHERE id=?');$q->execute([$id]);$old=$q->fetch();if(!$old)throw new RuntimeException('Ficha inexistente.');$image=$image?:$old['image'];db()->prepare('UPDATE commerce_directory SET user_id=?,name=?,local_number=?,image=?,description=?,active=?,featured=?,sort_order=?,updated_at=NOW() WHERE id=?')->execute([$uid,$name,$number,$image,$description,$active,$featured,$sort,$id]);}
 else{db()->prepare('INSERT INTO commerce_directory (user_id,name,local_number,image,description,active,featured,sort_order) VALUES (?,?,?,?,?,?,?,?)')->execute([$uid,$name,$number,$image,$description,$active,$featured,$sort]);}
 flash('success','Ficha comercial guardada.');redirect('commerces.php');
}
$editId=max(0,(int)($_GET['edit']??0));$editing=null;if($editId){$st=db()->prepare('SELECT * FROM commerce_directory WHERE id=?');$st->execute([$editId]);$editing=$st->fetch()?:null;}
$sellers=db()->query("SELECT u.id,u.username,COALESCE(NULLIF(p.display_name,''),u.username) display_name FROM users u JOIN profiles p ON p.user_id=u.id WHERE u.status='active' ORDER BY display_name LIMIT 2000")->fetchAll();
$rows=db()->query("SELECT d.*,u.username FROM commerce_directory d JOIN users u ON u.id=d.user_id ORDER BY d.featured DESC,d.sort_order,d.id DESC")->fetchAll();
require __DIR__.'/partials/header.php';?>
