<?php if(!empty($editing['image'])):?><img style="max-width:230px;max-height:150px;object-fit:cover;border-radius:12px" src="<?=url($editing['image'])?>" alt="Imagen actual"><?php endif;?>
<div class="admin-grid cols-2 mt-20"><label>Orden<input type="number" name="sort_order" min="0" max="9999" value="<?= (int)($editing['sort_order']??0) ?>"></label><div><label class="check-card"><input type="checkbox" name="active" <?=!isset($editing)||$editing['active']?'checked':''?>> Visible</label><label class="check-card"><input type="checkbox" name="featured" <?=!empty($editing['featured'])?'checked':''?>> Destacado</label></div></div>
